CREATE TABLE IF NOT EXISTS retainer_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, project_id uuid NOT NULL, period_start date NOT NULL, period_end date NOT NULL, timezone_snapshot text NOT NULL, fee_snapshot numeric(12,2) NOT NULL, currency_snapshot text NOT NULL, included_minutes_snapshot integer NOT NULL, overage_policy_snapshot text NOT NULL, overage_rate_snapshot numeric(12,2), approved_minutes integer NOT NULL DEFAULT 0, overage_minutes integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'open', invoice_generation integer NOT NULL DEFAULT 0, locked_at timestamptz, invoiced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id), UNIQUE(project_id,period_start,period_end), FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id) ON DELETE RESTRICT, CHECK(status IN ('open','locked','invoiced')));
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS retainer_period_id uuid;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='time_entries_retainer_period_workspace_fk') THEN ALTER TABLE time_entries ADD CONSTRAINT time_entries_retainer_period_workspace_fk FOREIGN KEY(retainer_period_id,workspace_id) REFERENCES retainer_periods(id,workspace_id) ON DELETE RESTRICT; END IF; END $$;
